INSERT IGNORE INTO equipment_current_state(equipment_id,operating_status,communication_status,display_status,status_started_at,production_count,cycle_time,load_rate,current_amp,temperature,current_alarm,response_ms,last_good_received_at,collected_at) SELECT id,CASE WHEN id=9 THEN 'ROBOT_FAULT' WHEN id=10 THEN 'WAITING' WHEN id=12 THEN 'MANUAL' WHEN id=13 THEN 'TEACHING' WHEN id=15 THEN 'PLANNED_STOP' ELSE 'RUNNING' END,CASE WHEN id=14 THEN 'DISCONNECTED' ELSE 'CONNECTED' END,CASE WHEN id=14 THEN 'COMMUNICATION_LOSS' WHEN id=9 THEN 'ROBOT_FAULT' WHEN id=10 THEN 'WAITING' WHEN id=12 THEN 'MANUAL' WHEN id=13 THEN 'TEACHING' WHEN id=15 THEN 'PLANNED_STOP' ELSE 'RUNNING' END,CURRENT_TIMESTAMP(3)-INTERVAL (id*2) MINUTE,1000+id*30,12+id/10,45+id,10+id/5,38+id/4,IF(id=9,'E071 위치 불일치',NULL),20+id,IF(id=14,CURRENT_TIMESTAMP(3)-INTERVAL 7 MINUTE,CURRENT_TIMESTAMP(3)),CURRENT_TIMESTAMP(3) FROM equipment;
INSERT IGNORE INTO collection_health(equipment_id,last_received_at,last_good_received_at,success_rate,consecutive_failures,average_response_ms,missing_count,reconnect_count,data_quality) SELECT id,IF(id=14,CURRENT_TIMESTAMP(3)-INTERVAL 7 MINUTE,CURRENT_TIMESTAMP(3)),IF(id=14,CURRENT_TIMESTAMP(3)-INTERVAL 7 MINUTE,CURRENT_TIMESTAMP(3)),IF(id=14,91.2,99.9),IF(id=14,24,0),20+id,IF(id=14,421,0),IF(id=14,6,0),IF(id=14,'BAD','GOOD') FROM equipment;
